function db(): PDO {
    static $pdo = null; global $config;
    if ($pdo instanceof PDO) return $pdo;
    $d = $config['db'];
    $dsn = sprintf('mysql:host=%s;port=%d;dbname=%s;charset=%s', $d['host'], $d['port'] ?? 3306, $d['database'], $d['charset'] ?? 'utf8mb4');
    $pdo = new PDO($dsn, $d['username'], $d['password'], [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC, PDO::ATTR_EMULATE_PREPARES=>false]);
    return $pdo;
}
function h(?string $v): string { return htmlspecialchars((string)$v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function money(float|int|string|null $v): string { return 'KES ' . number_format((float)$v, 2); }
function redirect(string $url): never { header('Location: ' . $url); exit; }
function flash(string $type, string $message): void { $_SESSION['flash'] = ['type'=>$type,'message'=>$message]; }
function csrf_token(): string { if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function verify_csrf(): void { if ($_SERVER['REQUEST_METHOD']==='POST' && !hash_equals($_SESSION['csrf'] ?? '', $_POST['_csrf'] ?? '')) { http_response_code(419); exit('Your session token expired. Refresh and try again.'); } }
function user(): ?array { return $_SESSION['user'] ?? null; }
function require_login(): array { if (!user()) redirect('?r=login'); return user(); }
function is_platform_admin(): bool { return (user()['role'] ?? '') === 'platform_admin'; }
function org_id(): int { return (int)(user()['organization_id'] ?? 0); }
function require_role(array $roles): void { require_login(); if (!in_array(user()['role'], $roles, true) && !is_platform_admin()) { http_response_code(403); exit('Access denied.'); } }
function audit(string $event, ?string $entity=null, ?int $id=null, array $details=[]): void {
    $u=user();
    $stmt=db()->prepare('INSERT INTO audit_logs (organization_id,user_id,event_type,entity_type,entity_id,details,ip_address) VALUES (?,?,?,?,?,?,?)');
    $stmt->execute([$u['organization_id'] ?? null,$u['id'] ?? null,$event,$entity,$id,json_encode($details,JSON_UNESCAPED_SLASHES),$_SERVER['REMOTE_ADDR'] ?? null]);
}
function clean_phone(string $phone): string { $p=preg_replace('/[^0-9+]/','',$phone); if (str_starts_with($p,'0')) return '+254'.substr($p,1); if (str_starts_with($p,'254')) return '+'.$p; return $p; }
function add_months_safe(DateTimeImmutable $date,int $months): DateTimeImmutable { $day=(int)$date->format('d'); $target=$date->modify('first day of this month')->modify(($months>=0?'+':'').$months.' months'); $last=(int)$target->modify('last day of this month')->format('d'); return $target->setDate((int)$target->format('Y'),(int)$target->format('m'),min($day,$last)); }
