function get_one(string $sql,array $params=[]): ?array { $s=db()->prepare($sql);$s->execute($params);$r=$s->fetch();return $r?:null; }
function get_all(string $sql,array $params=[]): array { $s=db()->prepare($sql);$s->execute($params);return $s->fetchAll(); }
function post_string(string $key,int $max=255): string { return mb_substr(trim((string)($_POST[$key]??'')),0,$max); }
function post_amount(string $key): float { $v=(string)($_POST[$key]??'0'); if(!is_numeric($v)) throw new RuntimeException('Enter a valid amount.'); $f=round((float)$v,2); if($f<0) throw new RuntimeException('Amounts cannot be negative.'); return $f; }
function app_error(Throwable $e): void { global $config; error_log('[FoneFlex] '.$e); if(!empty($config['app_debug'])) { http_response_code(500); echo '<pre class="debug">'.h($e->getMessage()).'</pre>'; } else { flash('error','The operation could not be completed. Please contact support.'); redirect('?r=dashboard'); } }
function allocate_payment_record(int $paymentId, int $agreementId, float $amount, int $organizationId, float $commissionRate, bool $principalOnly=false): array {
    $left=$amount; $principalAlloc=0.0; $interestAlloc=0.0;
    $schedules=get_all('SELECT * FROM installment_schedules WHERE agreement_id=? AND organization_id=? AND status IN ("pending","partial") ORDER BY due_date,installment_no FOR UPDATE',[$agreementId,$organizationId]);
    foreach($schedules as $s){
        if($left<=0.0001) break;
        $pr=max(0,(float)$s['principal_due']-(float)$s['principal_paid']);
        $ir=$principalOnly?0:max(0,(float)$s['interest_due']-(float)$s['interest_paid']);
        $total=$pr+$ir; if($total<=0) continue;
        $apply=min($left,$total);
        if($principalOnly){$pPart=$apply;$iPart=0.0;}else{$iPart=round($apply*($ir/$total),2);$pPart=round($apply-$iPart,2);if($apply >= $total-0.0001){$pPart=$pr;$iPart=$ir;}if($pPart>$pr){$iPart+=$pPart-$pr;$pPart=$pr;}if($iPart>$ir){$pPart+=$iPart-$ir;$iPart=$ir;}}
        $newPrPaid=round((float)$s['principal_paid']+$pPart,2);$newIrPaid=round((float)$s['interest_paid']+$iPart,2);$newStatus=(((float)$s['principal_due']-$newPrPaid)+((float)$s['interest_due']-$newIrPaid))<=0.005?'paid':'partial';db()->prepare('UPDATE installment_schedules SET principal_paid=?,interest_paid=?,status=? WHERE id=?')->execute([$newPrPaid,$newIrPaid,$newStatus,$s['id']]);
        $principalAlloc+=$pPart;$interestAlloc+=$iPart;$left=round($left-$apply,2);
    }
    db()->prepare('UPDATE payments SET principal_allocated=?,interest_allocated=? WHERE id=?')->execute([$principalAlloc,$interestAlloc,$paymentId]);
    $commission=calculate_foneflex_commission($interestAlloc,$commissionRate);
    if($commission>0) db()->prepare('INSERT INTO platform_commissions(organization_id,agreement_id,payment_id,interest_collected,commission_rate,commission_amount) VALUES(?,?,?,?,?,?)')->execute([$organizationId,$agreementId,$paymentId,$interestAlloc,$commissionRate,$commission]);
    return ['principal'=>$principalAlloc,'interest'=>$interestAlloc,'remaining_unallocated'=>$left];
}

