    if(!$name||!filter_var($bemail,FILTER_VALIDATE_EMAIL)||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12) throw new RuntimeException('Complete all required fields and use a password of at least 12 characters.');
