ct name="frequency"><option value="weekly">Weekly</option><option value="fortnightly">Fortnightly</option><option value="monthly">Monthly</option><option value="daily">Daily</option></select></div><div><label>First due date</label><input required type="date" name="first_due_date" min="'.date('Y-m-d').'" value="'.date('Y-m-d',strtotime('+7 days')).'"></div><div><label>Deposit channel</label><select name="deposit_channel"><option value="cash">Cash</option><option value="bank">Bank transfer (pending verification)</option><option value="mpesa">M-Pesa (pending verification)</option></select></div><div><label>Deposit transaction reference (optional)</label><input name="deposit_reference"></div></div><label class="checkline"><input type="checkbox" name="agreement_acknowledged" value="1" required> I confirm that the customer has reviewed and acknowledged the written hire-purchase agreement and that a signed copy will be retained.</label><label class="checkline"><input type="checkbox" name="device_notice_acknowledged" value="1" required> I confirm that the customer has received and acknowledged the device-management disclosure, including eligibility limitations and available support.</label><div class="info-note">Reducing-balance method: interest for each period = opening principal balance × periodic rate. The periodic rate is the nominal annual rate divided by 365 (daily), 52 (weekly), 26 (fortnightly), or 12 (monthly). The total agreed interest is calculated automatically from the complete schedule. A bank or M-Pesa deposit remains pending and the agreement stays under review until verified. FoneFlex&#39;s share is calculated only as interest is actually collected.</div><button class="btn primary full">Create agreement & schedule</button></form></div>';echo '<script>
(function(){
  const form = document.querySelector("#agreementModal form");
  if (!form) return;
  const field = name => form.elements.namedItem(name);
  const interestOutput = document.getElementById("ffTotalInterestPreview");
  const installmentOutput = document.getElementById("ffInstallmentPreview");
  const currency = value => "KES " + Number(value).toLocaleString("en-KE", {minimumFractionDigits: 2, maximumFractionDigits: 2});
  function recalculate(){
    const cash = Number(field("cash_price")?.value || 0);
    const deposit = Number(field("deposit")?.value || 0);
    const rateInput = field("annual_interest_rate")?.value ?? "";
    const rate = Number(rateInput);
    const count = Number(field("number_of_installments")?.value || 0);
    const frequency = field("frequency")?.value || "monthly";
    const financed = Math.max(0, cash - deposit);
    const periods = {daily:365, weekly:52, fortnightly:26, monthly:12}[frequency] || 12;
    if (rateInput.trim() === "" || financed <= 0 || count < 1 || count > 60 || rate < 0 || rate > 100) {
      interestOutput.value = "—";
      installmentOutput.value = "—";
      return;
    }
    const periodicRate = (rate / 100) / periods;
    const payment = periodicRate === 0 ? financed / count : financed * periodicRate / (1 - Math.pow(1 + periodicRate, -count));
    let balance = financed;
    let totalInterest = 0;
    for (let period = 1; period <= count; period++) {
      const interest = Math.round(balance * periodicRate * 100) / 100;
      const principal = period === count ? balance : Math.min(balance, Math.round((payment - interest) * 100) / 100);
      totalInterest += interest;
      balance = Math.max(0, Math.round((balance - principal) * 100) / 100);
    }
    interestOutput.value = currency(totalInterest);
    installmentOutput.value = currency(payment);
  }
  ["cash_price", "deposit", "annual_interest_rate", "number_of_installments", "frequency", "deposit_channel"].forEach(name => {
    const control = field(name);
    if (control) { control.addEventListener("input", recalculate); control.addEventListener("change", recalculate); }
  });
  recalculate();
})();
