cho '<tr><td><b>'.h($o['name']).'</b><small>'.h($o['business_email']).' · '.date('d M Y',strtotime($o['created_at'])).'</small></td><td>'.h($o['plan_name']??'—').'<small>'.(int)$o['users_count'].' users</small></td><td><form id="merchant-'.(int)$o['id'].'" method="post"></form><input form="merchant-'.(int)$o['id'].'" type="hidden" name="_csrf" value="'.h(csrf_token()).'"><input form="merchant-'.(int)$o['id'].'" type="hidden" name="action" value="merchant_update"><input form="merchant-'.(int)$o['id'].'" type="hidden" name="organization_id" value="'.(int)$o['id'].'"><select form="merchant-'.(int)$o['id'].'" name="status"><option '.($o['status']==='trial'?'selected':'').' value="trial">trial</option><option '.($o['status']==='active'?'selected':'').' value="active">active</option><option '.($o['status']==='past_due'?'selected':'').' value="past_due">past due</option><option '.($o['status']==='suspended'?'selected':'').' value="suspended">suspended</option><option '.($o['status']==='closed'?'selected':'').' value="closed">closed</option></select></td><td><input form="merchant-'.(int)$o['id'].'" class="mini-input" type="number" min="0" max="100" step="0.01" name="commission_rate" value="'.h((string)$o['commission_rate']).'"></td><td><input form="merchant-'.(int)$o['id'].'" class="mini-input" type="number" min="0" step="0.01" name="monthly_fee" value="'.h((string)($sub['monthly_fee']??0)).'"></td><td class="amount">'.money($o['commission_due']).'</td><td><button form="merchant-'.(int)$o['id'].'" class="tiny-btn">Save</button></td></tr>';}if(!$orgs)echo '<tr><td colspan="7" class="empty">No merchants registered.</td></tr>';echo '</tbody></table></div></div>';layout_end();exit;
